import { createElement as h } from "react";
import { hrefFor, PageHead } from "../components/Layout.jsx";
import { ChannelSelect } from "../components/ChannelSelect.jsx";
import { Markdown } from "../components/Markdown.jsx";
import { channelById } from "../source.js";
import { useDocument } from "../use-docs.js";

// The standard library page renders docs/stdlib/reference.md from GitHub.
//
// The reference is generated by `oq doc` in the language repository and validated by that
// repository's check-docs-sync, so it cannot advertise a function that does not exist. The
// site renders it at request time instead of shipping a copy that could drift.

const STDLIB_PATH = "docs/stdlib/reference.md";

export function StdlibPage({ query = {} }) {
  const channel = channelById(query.ref);
  const { status, data, error, retry } = useDocument(channel.ref, STDLIB_PATH);

  return h(
    "div",
    null,
    h(PageHead, {
      eyebrow: "Standard library",
      title: "Standard library",
      lead: "Generated from the implementation by oq doc and fetched from GitHub when you open this page. If a function is listed here, it exists, and the language repository's CI fails when the reference is out of date.",
    }),

    h(ChannelSelect, { ref: channel.ref, path: "/stdlib.html" }),

    status === "loading" && !data
      ? h(
          "div",
          { className: "doc-status", role: "status", "aria-live": "polite" },
          h("p", null, "Fetching the generated reference from GitHub…"),
          h("div", { className: "skeleton", "aria-hidden": "true" }),
        )
      : null,

    status === "error" && !data
      ? h(
          "div",
          { className: "doc-status doc-status-error", role: "alert" },
          h("h2", null, "The standard library reference could not be loaded"),
          h("p", null, error?.message ?? "GitHub could not be reached."),
          h(
            "p",
            null,
            h(
              "a",
              { href: error?.url ?? "https://github.com/Oqthara/oqthara/blob/main/docs/stdlib/reference.md" },
              "Read the generated reference on GitHub",
            ),
            " · ",
            h("button", { type: "button", className: "retry", onClick: retry }, "Try again"),
          ),
        )
      : null,

    data
      ? h(
          "div",
          null,
          h(Markdown, { markdown: data.markdown, path: data.path, ref: channel.ref }),
          h(
            "p",
            { className: "doc-source" },
            "Rendered from ",
            h("a", { href: data.sourceUrl }, h("code", null, STDLIB_PATH)),
            " at ",
            h("code", null, channel.ref),
            " · ",
            h("a", { href: hrefFor("/docs.html") }, "All documentation"),
          ),
        )
      : null,
  );
}
